3	import { useRouter, usePathname } from "next/navigation";
4	import { useAuth } from "@/hooks/useAuth";
5	import { useWorkspace } from "@/hooks/useWorkspace";
6	import AppHeader from "@/components/AppHeader";
7	import JobSidebar from "@/components/JobSidebar";
8	import AgencySidebar from "@/components/AgencySidebar";
9	import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
10	
11	/**
12	 * Shared layout with persistent JobSidebar + AppHeader.
13	 * Used by all authenticated pages (Settings, Billing, Admin, etc.).
14	 *
15	 * `defaultOpen` comes from the server-read `sidebar:state` cookie via
16	 * app/(app)/layout.tsx so the initial paint matches the user's last
17	 * toggle — prevents the expanded→collapsed flash on refresh.
18	 */
19	const SidebarLayout = ({
20	  children,
21	  defaultOpen = true,
22	}: {
23	  children: React.ReactNode;
24	  defaultOpen?: boolean;
25	}) => {
26	  const { user } = useAuth();
27	  const router = useRouter();
28	  const pathname = usePathname() ?? "/";
29	  const { activeKey: workspace } = useWorkspace();
30	
31	  // Both "/" and "/jobs" render the same <Index/> component. The sidebar
32	  // callback items (Dashboard / My Jobs) need active highlighting derived
33	  // from the current pathname since they don't have their own URLs in
34	  // the routes table — they're internal view toggles inside Index.tsx.
35	  const showDashboard = pathname === "/";
36	  const showMyJobs = pathname === "/jobs" || pathname.startsWith("/jobs/");
37	
38	  return (
39	    <SidebarProvider defaultOpen={defaultOpen} className="h-svh overflow-hidden">
40	      {workspace === "agency" ? (
41	        <AgencySidebar />
42	      ) : (
43	        <JobSidebar
44	          showDashboard={showDashboard}
45	          showMyJobs={showMyJobs}
46	          onNewJob={() => router.push("/?new=1")}
47	          onDashboard={() => router.push("/")}
48	          onMyJobs={() => router.push("/jobs")}
49	          onAuthRequired={() => router.push("/auth")}
50	          isAuthenticated={!!user}
51	        />
52	      )}
53	      <SidebarInset className="h-svh overflow-hidden bg-sidebar p-2 pl-0">
54	        <div className="h-full flex flex-col rounded-xl border bg-background overflow-hidden">
55	          <AppHeader />
56	          <div className="flex items-center h-10 px-4 md:hidden">
57	            <SidebarTrigger />
58	          </div>
59	          <div className="flex-1 overflow-y-auto">
60	            {children}
61	          </div>
62	        </div>
63	      </SidebarInset>
64	    </SidebarProvider>
65	  );
66	};
67	
68	export default SidebarLayout;
